def chunks(text):
 if len(text)>2<<20 or re.search(r'(?m)^(?:FAIL|\s*--- (?:FAIL|SKIP):)',text):raise ValueError('failed/skipped/oversized restart evidence')
 found=re.findall(r'(?ms)^=== RUN   (Test\w+)\n(.*?)^--- PASS: (Test\w+) \(([0-9.]+)s\)$',text)
 if any(n!=end for n,body,end,sec in found) or re.findall(r'(?m)^--- PASS: (Test\w+) \([0-9.]+s\)$',text)!=[n for n,_,_,_ in found]:raise ValueError('invalid parent completion')
 return found
def controls(text,prefix,names):
 rows=re.findall(prefix+r' ([^\n]+)',text)
 if len(rows)!=1 or len(rows[0].split())!=len(names) or set(rows[0].split())!={n+'=pass' for n in names}:raise ValueError('missing/duplicate/unknown/failed restart controls')
def validate(text,scope):
 found=chunks(text)
 if scope=='publication':
  wanted={'TestNativeClosedStartupPublicationUFS','TestNativeClosedStartupPublicationZFS','TestNativeClosedStartupPublicationCuts'}
  if len(found)!=3 or {n for n,_,_,_ in found}!=wanted:raise ValueError('three distinct actual publication parents required')
  for name,body,_,_ in found:
   if name.endswith('Cuts'):controls(body,'CLOSED_STARTUP_CUT_RESULT',CUTS);kind='ufs'
   else:
    kind='ufs' if name.endswith('UFS') else 'zfs';controls(body,'CLOSED_STARTUP_PUBLICATION_'+kind.upper()+'_RESULT',STORAGE)
   if re.findall('STATE_BACKING_RESULT ([^\n]+)',body)!=[name+' filesystem='+kind+' softupdates=off teardown=pass']:raise ValueError('actual publication backing teardown required')
  for marker,count in [('CLOSED_STARTUP_PUBLICATION_(?:UFS|ZFS)_RESULT ',2),('CLOSED_STARTUP_CUT_RESULT ',1),('STATE_BACKING_RESULT ',3)]:
   if len(re.findall(marker,text))!=count:raise ValueError('extra/missing publication marker')
 elif scope=='owner':
  wanted={'TestNativeClosedStartupOwnerUFS','TestNativeClosedStartupOwnerZFS','TestNativeExecutionStartupUFS','TestNativeExecutionStartupZFS'}
  if len(found)!=4 or {n for n,_,_,_ in found}!=wanted:raise ValueError('four distinct actual startup parents required')
  old=''
  for name,body,end,sec in found:
   if name.startswith('TestNativeExecutionStartup'):old+='=== RUN   '+name+'\n'+body+'--- PASS: '+end+' ('+sec+'s)\n';continue
   kind='ufs' if name.endswith('UFS') else 'zfs';controls(body,'CLOSED_STARTUP_OWNER_'+kind.upper()+'_RESULT',OWNER)
   for marker,value in [('DOMAIN','filesystems=pass directories=pass'),('DATA','restored=pass')]:
    if re.findall('CLOSED_STARTUP_OWNER_'+marker+r'_TEARDOWN ([^\n]+)',body)!=[kind+' '+value]:raise ValueError('independent owner fixture teardown required')
  path=Path(__file__).with_name('check-execution-startup-evidence.py');spec=importlib.util.spec_from_file_location('original_startup',path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);m.validate(old)
  for marker in ['CLOSED_STARTUP_OWNER_(?:UFS|ZFS)_RESULT ','CLOSED_STARTUP_OWNER_DOMAIN_TEARDOWN ','CLOSED_STARTUP_OWNER_DATA_TEARDOWN ']:
   if len(re.findall(marker,text))!=2:raise ValueError('extra/missing owner marker')
 else:raise ValueError('unknown restart scope')
if __name__=='__main__':validate(Path(sys.argv[1]).read_text(),sys.argv[2])
